import "fmt"

func firstN(s string, n int) string {
	count := 0
	for i := range s {
		if count == n {
			return s[:i]
		}
		count++
	}
	return s
}

func main() {
	fmt.Println(firstN("Ўзбекистон", 4))
	fmt.Println(firstN("Salom", 10))
	fmt.Println(firstN("Hi😀there", 3))
}

