import "fmt"

func caesar(s string, shift int) string {
	out := []byte(s)
	for i, c := range out {
		if c >= 'a' && c <= 'z' {
			out[i] = 'a' + (c-'a'+byte(shift))%26
		}
	}
	return string(out)
}

func main() {
	enc := caesar("salom", 3)
	fmt.Println(enc)
	fmt.Println(caesar("xyz", 3))
	fmt.Println(caesar(enc, 23))
}

package main

import (
	"fmt"
	"strings"
	"unicode"
)

var table = map[rune]string{
	'ў': "o'", 'з': "z", 'б': "b", 'е': "e", 'к': "k", 'и': "i", 'с': "s",
	'т': "t", 'о': "o", 'н': "n", 'а': "a", 'л': "l", 'м': "m", 'ш': "sh",
}

func toLatin(s string) string {
	var out []string
	for _, r := range s {
		lat, ok := table[unicode.ToLower(r)]
		if !ok {
			out = append(out, string(r))
			continue
		}
		if unicode.IsUpper(r) {
			lat = strings.ToUpper(lat[:1]) + lat[1:]
		}
		out = append(out, lat)
	}
	return strings.Join(out, "")
}

func main() {
	fmt.Println(toLatin("Ўзбекистон"))
	fmt.Println(toLatin("Салом, Тошкент!"))
}

