func sorted(s string) string {
	r := []rune(s)
	slices.Sort(r)
	return string(r)
}

func isAnagram(a, b string) bool {
	return sorted(a) == sorted(b)
}

func main() {
	fmt.Println(isAnagram("listen", "silent"))
	fmt.Println(isAnagram("ота", "она"))
