func toSnake(s string) string {
	var parts []string
	start := 0
	for i, r := range s {
		if i > 0 && unicode.IsUpper(r) {
			parts = append(parts, strings.ToLower(s[start:i]))
			start = i
		}
	}
	parts = append(parts, strings.ToLower(s[start:]))
	return strings.Join(parts, "_")
}

