func findAll(s, sub string) []int {
	var positions []int
	offset := 0
	for {
		i := strings.Index(s[offset:], sub)
		if i < 0 {
			break
		}
		positions = append(positions, offset+i)
		offset += i + len(sub)
	}
	return positions
}

