func wrap(text string, width int) []string {
	var lines []string
	current := ""
	for w := range strings.FieldsSeq(text) {
		if current != "" && len(current)+1+len(w) > width {
			lines = append(lines, current)
			current = w
			continue
		}
		if current != "" {
			current += " "
		}
		current += w
	}
	if current != "" {
		lines = append(lines, current)
	}
	return lines
}

func main() {
	text := "Go tili oddiy, tez va ishonchli dasturlash tilidir"
	for _, line := range wrap(text, 20) {
		fmt.Printf("|%-20s|\n", line)
