func calc(expr string) (float64, error) {
	parts := strings.Fields(expr)
	if len(parts) != 3 {
		return 0, fmt.Errorf("noto'g'ri ifoda: %q", expr)
	}
	a, err := strconv.ParseFloat(parts[0], 64)
	if err != nil {
		return 0, err
	}
	b, err := strconv.ParseFloat(parts[2], 64)
	if err != nil {
		return 0, err
	}
	switch parts[1] {
	case "+":
		return a + b, nil
	case "-":
		return a - b, nil
	case "*":
		return a * b, nil
	case "/":
		return a / b, nil
	}
	return 0, fmt.Errorf("noma'lum amal: %q", parts[1])
}

func main() {
	for _, e := range []string{"12 + 30", "7.5 * 2", "9 / 4", "5 ^ 2", "a + 1", "1 +"} {
		res, err := calc(e)
		fmt.Println(e, "=>", res, err)
	}
}

