func parseColor(hex string) (r, g, b uint8, err error) {
	if len(hex) != 7 || hex[0] != '#' {
		return 0, 0, 0, fmt.Errorf("noto'g'ri rang: %q", hex)
	}
	var v [3]uint64
	for i := range 3 {
		v[i], err = strconv.ParseUint(hex[1+2*i:3+2*i], 16, 8)
		if err != nil {
			return 0, 0, 0, err
		}
	}
	return uint8(v[0]), uint8(v[1]), uint8(v[2]), nil
}

